// «Performance турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

// Дээд хэсэг: 200px скролл, мөр 40px, цонх 400px, нийт 1000 мөр.
window.RANGE = visibleRange(200, 40, 400, 1000);
// Хамгийн доод хэсэг: end нь нийтээс хэтрэхгүй.
window.RANGE_END = visibleRange(39600, 40, 400, 1000);

panel("ok", "top", "Харагдах муж (дээр)", [JSON.stringify(window.RANGE)]);
panel("ok", "bot", "Харагдах муж (доор — хязгаарлагдсан)", [JSON.stringify(window.RANGE_END)]);
document.body.dataset.ready = "1";

